from __future__ import annotations

import base64
import sys
from pathlib import Path

PACKAGE_ID = "contollo.cvis.automation.clean-base-class-naming-doc-standard.native-path-update"
PACKAGE_VERSION = "1.2.5-preview"

# Self-contained file payload. The ZIP intentionally has no payload/ entries because
# the current runner can fail while extracting nested payload paths.
EMBEDDED_FILES_B64 = {
  "CVIS.Automation.Tests/README.md": "",
  "CVIS.FunctionalTesting/Base/BaseAutomationCvisApiTest.cs": "",
  "CVIS.FunctionalTesting/Base/BaseAutomationCvisDatabaseTest.cs": "",
  "CVIS.FunctionalTesting/Base/BaseAutomationCvisTest.cs": "",
  "CVIS.FunctionalTesting/Base/BaseFunctionalTest.cs": "",
  "CVIS.FunctionalTesting/Base/README.md": "",
  "CVIS.FunctionalTesting/CVIS.FunctionalTesting.csproj": "",
  "CVIS.FunctionalTesting/Config/README.md": "",
  "CVIS.FunctionalTesting/Helpers/ApiClient.cs": "",
  "CVIS.FunctionalTesting/Helpers/README.md": "",
  "CVIS.FunctionalTesting/README.md": "",
  "CVIS.FunctionalTesting/Reporting/README.md": "",
  "CVIS.Playwright.NUnitCompat/Base/BaseAutomationCvisPlaywrightBrowserTest.cs": "",
  "CVIS.Playwright.NUnitCompat/Base/BaseAutomationCvisPlaywrightPageTabTest.cs": "",
  "CVIS.Playwright.NUnitCompat/Base/CVISPageTest.cs": "",
  "CVIS.Playwright.NUnitCompat/Base/CVISPlaywrightTest.cs": "",
  "CVIS.Playwright.NUnitCompat/Base/README.md": "",
  "CVIS.Playwright.NUnitCompat/README.md": "",
  "CVIS.Playwright.NUnitCompat/Reporting/README.md": "",
  "README.md": "",
  "docs/README-STANDARD.md": "",
  "hyperexecute-cvis-authoritative-nunit.yaml": "",
  "scripts/README.md": "",
  "scripts/run-cvis-authoritative-report-local.ps1": ""
}

REQUIRED_TEXT = {
  "CVIS.FunctionalTesting/Base/BaseAutomationCvisApiTest.cs": [
    "public abstract class BaseAutomationCvisApiTest : BaseAutomationCvisTest",
    "protected ApiClient ApiClient"
  ],
  "CVIS.FunctionalTesting/Base/BaseAutomationCvisDatabaseTest.cs": [
    "public abstract class BaseAutomationCvisDatabaseTest : BaseAutomationCvisTest",
    "OpenDatabaseConnectionAsync",
    "AssertDatabaseConnectionCanOpenAsync"
  ],
  "CVIS.FunctionalTesting/Base/BaseAutomationCvisTest.cs": [
    "public abstract class BaseAutomationCvisTest",
    "[OneTimeSetUp]",
    "[SetUp]",
    "[TearDown]",
    "[OneTimeTearDown]",
    "protected virtual Task OnFixtureSetUpAsync()"
  ],
  "CVIS.Playwright.NUnitCompat/Base/BaseAutomationCvisPlaywrightBrowserTest.cs": [
    "public abstract class BaseAutomationCvisPlaywrightBrowserTest : BaseAutomationCvisTest",
    "protected IBrowser Browser"
  ],
  "CVIS.Playwright.NUnitCompat/Base/BaseAutomationCvisPlaywrightPageTabTest.cs": [
    "public abstract class BaseAutomationCvisPlaywrightPageTabTest : BaseAutomationCvisPlaywrightBrowserTest",
    "protected IPage Page"
  ]
}


def fail(message: str) -> None:
    print(f"ERROR: {message}", file=sys.stderr)
    sys.exit(1)


def decode_files() -> dict[str, str]:
    return {
        path: base64.b64decode(data.encode("ascii")).decode("utf-8")
        for path, data in EMBEDDED_FILES_B64.items()
    }


def strip_csharp_comments_and_strings(text: str) -> str:
    result: list[str] = []
    i = 0
    length = len(text)
    in_line_comment = False
    in_block_comment = False
    in_string = False
    in_verbatim_string = False
    in_char = False

    while i < length:
        ch = text[i]
        nxt = text[i + 1] if i + 1 < length else ""

        if in_line_comment:
            if ch == "\n":
                in_line_comment = False
                result.append(ch)
            else:
                result.append(" ")
            i += 1
            continue

        if in_block_comment:
            if ch == "*" and nxt == "/":
                in_block_comment = False
                result.extend("  ")
                i += 2
            else:
                result.append("\n" if ch == "\n" else " ")
                i += 1
            continue

        if in_string:
            if in_verbatim_string:
                if ch == '"' and nxt == '"':
                    result.extend("  ")
                    i += 2
                    continue
                if ch == '"':
                    in_string = False
                    in_verbatim_string = False
                result.append("\n" if ch == "\n" else " ")
                i += 1
                continue

            if ch == "\\":
                result.extend("  ")
                i += 2
                continue
            if ch == '"':
                in_string = False
            result.append("\n" if ch == "\n" else " ")
            i += 1
            continue

        if in_char:
            if ch == "\\":
                result.extend("  ")
                i += 2
                continue
            if ch == "'":
                in_char = False
            result.append("\n" if ch == "\n" else " ")
            i += 1
            continue

        if ch == "/" and nxt == "/":
            in_line_comment = True
            result.extend("  ")
            i += 2
            continue

        if ch == "/" and nxt == "*":
            in_block_comment = True
            result.extend("  ")
            i += 2
            continue

        if ch == "@" and nxt == '"':
            in_string = True
            in_verbatim_string = True
            result.extend("  ")
            i += 2
            continue

        if ch == '"':
            in_string = True
            in_verbatim_string = False
            result.append(" ")
            i += 1
            continue

        if ch == "'":
            in_char = True
            result.append(" ")
            i += 1
            continue

        result.append(ch)
        i += 1

    return "".join(result)


def validate_balanced_csharp(path: str, text: str) -> None:
    cleaned = strip_csharp_comments_and_strings(text)
    pairs = {"{": "}", "(": ")", "[": "]"}
    opening = set(pairs.keys())
    closing = set(pairs.values())
    stack: list[tuple[str, int]] = []

    for index, ch in enumerate(cleaned):
        if ch in opening:
            stack.append((ch, index))
        elif ch in closing:
            if not stack:
                fail(f"{path} has unmatched closing {ch} at character {index}")
            last, last_index = stack.pop()
            if pairs[last] != ch:
                fail(f"{path} has mismatched {last} at {last_index} and {ch} at {index}")

    if stack:
        last, last_index = stack[-1]
        fail(f"{path} has unmatched opening {last} at character {last_index}")


def apply_files(target_root: Path, files: dict[str, str]) -> None:
    for relative_path, content in files.items():
        if relative_path.startswith("payload/") or "/payload/" in relative_path:
            fail(f"Embedded target path must not use payload/: {relative_path}")

        destination = target_root / Path(relative_path)
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(content, encoding="utf-8", newline="")
        print(f"Applied: {relative_path}")


def validate_expected_files(target_root: Path, files: dict[str, str]) -> None:
    for relative_path in files:
        target_path = target_root / Path(relative_path)
        if not target_path.exists():
            fail(f"Expected file was not written: {relative_path}")

    for relative_path, expected_fragments in REQUIRED_TEXT.items():
        text = (target_root / Path(relative_path)).read_text(encoding="utf-8-sig")
        for fragment in expected_fragments:
            if fragment not in text:
                fail(f"{relative_path} is missing required text: {fragment}")

    for relative_path in files:
        if relative_path.endswith(".cs"):
            text = (target_root / Path(relative_path)).read_text(encoding="utf-8-sig")
            validate_balanced_csharp(relative_path, text)

    root_readme = (target_root / "README.md").read_text(encoding="utf-8-sig")
    if "BaseAutomationCvisTest" not in root_readme:
        fail("README.md does not document BaseAutomationCvisTest")

    standard = target_root / "docs" / "README-STANDARD.md"
    if not standard.exists():
        fail("docs/README-STANDARD.md was not created")


def main() -> None:
    target_root = Path.cwd()
    files = decode_files()
    print(f"Applying {PACKAGE_ID} {PACKAGE_VERSION}")
    print("Native-path update mode: runner applies target files directly; applier also writes root README and validates all target files.")
    apply_files(target_root, files)
    validate_expected_files(target_root, files)
    print("Validation complete: embedded files applied and required text checks passed.")
    print("DocOps note: docs/context.md, docs/memory.md, and docs/DECISIONS.md are handled by the RDEL runner DocumentationOperations.")


if __name__ == "__main__":
    main()
